"""Mechanical comparisons and report generation; never chooses a fitted policy."""
import json
from pathlib import Path
import numpy as np
import pandas as pd
from src.local_30_evaluation import bootstrap_weights,divide,interval
from .baseline import ROOT


def write_report(output,protocol):
    s=pd.read_csv(output/'event_summary.csv');p=pd.read_csv(output/'event_per_recording.csv')
    new=s[s.FeatureSet.isin(['base10','context18'])].copy()
    index=['Target','Horizon_s','Model','Budget','Window_s','Subset']
    before=s[s.FeatureSet.eq('frozen30')].set_index(index)
    weights=bootstrap_weights(protocol['bootstrap_repetitions'],protocol['bootstrap_seed'])
    comparisons=[];paired=[]
    for row in new.itertuples():
        key=tuple(getattr(row,k) for k in index);old=before.loc[key]
        record=p
        for k,v in zip(index,key):record=record[record[k].eq(v)]
        a=record[record.FeatureSet.eq(row.FeatureSet)&record.ScoreSpace.eq(row.ScoreSpace)].set_index('Record').reindex(range(1,31))
        b=record[record.FeatureSet.eq('frozen30')].set_index('Record').reindex(range(1,31))
        np.testing.assert_array_equal(a.Eligible_Events,b.Eligible_Events)
        rowkey={k:getattr(row,k) for k in index}|dict(FeatureSet=row.FeatureSet,ScoreSpace=row.ScoreSpace)
        point={}
        for metric in ['Detected','Eligible_Events','Missed_Events','Sensitivity','False_Alarm_Starts_Per_Hour','Alarm_Active_Fraction','Lead_Median_s']:
            point['Before_'+metric]=old[metric];point['After_'+metric]=getattr(row,metric)
        point['All_Exposed_Records_Within_Budget']=bool(((a.False_Alarm_Starts_Per_Hour<=row.Budget+1e-12)|a.Exposure_s.eq(0)).all())
        point['All_Exposed_Records_Within_Active_Cap']=bool(((a.Alarm_Active_Fraction<=.05+1e-12)|a.Exposure_s.eq(0)).all())
        comparisons.append(rowkey|point)
        def ratios(f):
            return dict(Sensitivity=divide(weights@f.Detected,weights@f.Eligible_Events),
                False_Alarm_Starts_Per_Hour=divide(3600*(weights@f.Off_Event_Alarm_Starts),weights@f.Exposure_s),
                Alarm_Active_Fraction=divide(weights@f.Alarm_Active_s,weights@f.Exposure_s))
        aa,bb=ratios(a),ratios(b)
        for metric in aa:paired.append(rowkey|dict(Metric=metric,Difference=getattr(row,metric)-old[metric],**interval(aa[metric]-bb[metric]),Replicates=len(weights)))
    c=pd.DataFrame(comparisons);c.to_csv(output/'before_after_comparison.csv',index=False)
    pd.DataFrame(paired).to_csv(output/'paired_recording_bootstrap.csv',index=False)
    primary=new[new.Subset.eq('all')&new.Window_s.eq(new.Horizon_s)]
    eligible=primary[(primary.Detected>0)&(primary.False_Alarm_Starts_Per_Hour<=primary.Budget+1e-12)&(primary.Alarm_Active_Fraction<=.05+1e-12)]
    chosen=c[c.Subset.eq('all')&c.Window_s.eq(c.Horizon_s)]
    strict=chosen[(chosen.After_Detected>0)&(chosen.After_False_Alarm_Starts_Per_Hour<=chosen.Budget+1e-12)&(chosen.After_Alarm_Active_Fraction<=.05+1e-12)&chosen.All_Exposed_Records_Within_Budget&chosen.All_Exposed_Records_Within_Active_Cap]
    display=primary[primary.Budget.eq(5)][['Target','Horizon_s','FeatureSet','ScoreSpace','Model','Detected','Eligible_Events','Missed_Events','False_Alarm_Starts_Per_Hour','Alarm_Active_Fraction','Lead_Median_s']]
    latency=pd.read_csv(output/'latency.csv')
    t=pd.read_csv(output/'timestamp_summary.csv')
    tsmall=t[t.Budget.eq(5)&t.Metric_Scope.eq('current_normal')&t.FeatureSet.isin(['base10','context18'])][['Target','Horizon_s','FeatureSet','ScoreSpace','Model','Recall','Precision','Specificity','PR_AUC_AP','FP','FN','Macro_PR_AUC_AP']]
    report=ROOT/'docs/ML_IMPROVEMENT_REPORT.md'
    outcome=(f'{len(eligible)} prespecified model/feature/score/label-horizon/budget conditions detected at least one event while meeting the pooled start budget and 5% active cap. {len(strict)} also met those constraints in every exposed held-out recording. '
             if len(eligible) else 'No tested condition detected an event while meeting both the pooled original start budget and 5% active cap. ')
    text='''# Controlled ML improvement experiments\n\n## Executive result\n\n'''+outcome+'''These are exploratory results on the same repeatedly inspected 30 recordings, not confirmatory validation or evidence for treatment. There is no test-selected deployment winner. The complete numerical before/after table includes all prespecified budgets, windows, horizons and conditions; apparent positive findings, if any, require further nested recording-grouped policy assessment and must not be selected from these outer outcomes.\n\n## Starting point and design\n\nThe [baseline audit](ML_IMPROVEMENT_BASELINE.md) was completed before experimental fitting. Original final policy: all four learned families, both 30-second targets and budgets 1/5/10 have 0/14 detections at W=30, 0/15 at W=5/10/15 and 0/3 severe-interest detections. Earlier high recall operates at excessive alert burden. All source/dataset/model/results/receipt bytes from the baseline snapshot remain protected.\n\nThe isolated runner uses the existing four estimator families and EXACT hyperparameters, with outer LORO, three recording-grouped inner folds, train-only imputation/scaling/model fitting, and seed 42. No random forest, LightGBM, boosting, hyperparameter search or PID/oxygen simulation was added: six onset-bearing recordings do not justify expanding the family search in this pass. No existing implementation bug was assumed from a negative result. Production code is untouched. Experimental in-memory estimator instances support the additional feature schema without changing production feature contracts or persisted models.\n\nFive settings were frozen before fitting: original 10 features with true trained label horizons 5/10/15/30 s; plus a single 18-feature causal-context ablation at 30 s. Both future-low and new-onset retain their original observed threshold/crossing definitions, using existing labeling helpers with an explicit horizon parameter. Short-horizon experiments use the SAME original complete-30s sample population within each target, not added tail samples. All event calculations retain common original strict current-normal exposure, ensuring eligible-event and burden denominators remain comparable. This intentionally sacrifices additional short-horizon eligibility to isolate comparisons. All 30 recordings remain in reporting/resampling, including four zero-exposure onset records. Recording IDs are not verified patient IDs.\n\nEight added current/past pulse features: 30-second amplitude mean/CV, rate mean/trend, interval CV, current amplitude/past mean ratio, recent 10-second pulse count and time since previous accepted pulse. The context is built on the entire pulse stream BEFORE label exclusions. These are causal cadence/morphology proxies, NOT validated SQI; no current/future SpO2, labels, ID, ECG timing or PTT is a predictor. Prefix/reset regressions cover this code. The training feature-analysis CSV records fold-specific positive/negative means and standardized differences; no feature was selected using held-out importance or outcomes.\n\nEach fit yields two prespecified score spaces: raw and empirical training-negative rank. Inner validation ranks use only negative FIT-row scores from that same inner estimator; outer ranks use only outer-training negative scores. This addresses a hypothesized score-scale transfer issue, not probability calibration. A sorted empirical CDF is nondecreasing but tied/discretized; training-score optimism can still transfer poorly.\n\nEach scalar cutoff uses ONLY the training OOF scores/events/exposure. The original fixed quantile grid and above-training-maximum candidate are retained, as are budgets 1/5/10 starts/evaluable hour and the 5% duration cap. Among feasible candidates, maximize chronological one-to-one event matches at the trained horizon, then fewer false starts, lower active duration and higher cutoff. There is no suppression, smoothing, relaxation or outer-outcome adjustment. For shorter label horizons this changes both label and selection window; it is not an isolated timing-only effect. All selections are frozen before held-out outcome evaluation; fold ledgers include exact permitted recordings, inner splits and OOF/reference hashes.\n\n## Numerical before/after comparisons\n\n`results/ml_improvement/run01/before_after_comparison.csv` contains every before/after event result, including 91/92 subsets. Frozen-original controls reuse the exact old 30-second scores and thresholds at every evaluation-label horizon; their `Trained_Horizon_s` remains 30, while new fits train at `Horizon_s`. Fixed always/never, periodic 1 s in 10 s, and pulse-rate >100 baselines have no trained horizon (`Trained_Horizon_s=0`). Comparing H=5 label results against a frozen H=30 model is an explicit control, not a claim that the original model was trained for 5 s. Original 30s/base10 raw score AND event-policy parity are asserted before accepting the run. Scores are compared with explicit floating serialization tolerance (1e-9 relative/1e-10 absolute), not byte-identical CSV text; the preflight cutoff differed from historical parsed OOF scores by round-off only. The 91/92 subset describes an episode containing those observed readings, not a separately trained severe threshold or guaranteed prediction of 91/92 within H.\n\nThe table below shows ALL tested learned conditions at research budget 5, with event matching W equal to label H. This budget is a display slice, not a selected winner. Other budgets and all four matching windows are fully saved.\n\n```text\n'''+display.to_string(index=False,float_format=lambda v:f'{v:.6g}')+'''\n```\n\nTimestamp results on the common current-normal population at that same display budget (AP is average precision, not trapezoidal PR area):\n\n```text\n'''+tsmall.to_string(index=False,float_format=lambda v:f'{v:.6g}')+'''\n```\n\n`timestamp_summary.csv` also reports FULL target populations (including ongoing-low future-low rows), pooled counts/metrics and clearly named defined-record macro metrics. `timestamp_per_recording.csv` distinguishes positive-containing from negative-only records; undefined precision/recall remains NaN. Event sensitivity is NOT timestamp recall; starts/hour is NOT false-positive timestamps/hour or legacy false target episodes/hour. Lead = observed onset minus actual matched alarm start. Each event/episode receives at most one credit; nearby events cannot reuse a start. W defines a look-back window, not a guaranteed minimum lead.\n\n## Uncertainty, robustness and ranking\n\nWhole-record bootstrap (2,000 paired draws, seed 20261015) produces conditional event sensitivity/burden/activity/lead intervals and paired changes against frozen-original controls. It does not establish patient independence, resample complete model fitting, correct multiple comparisons, or provide confirmatory model selection. Zero detections can produce a degenerate empirical [0,0] interval, not evidence that population sensitivity is exactly zero. AP has no resampled CI here. The influence CSV removes each recording's SAVED contributions in turn to describe concentration; it never removes a record from fitting/evaluation or tunes after seeing that influence.\n\nThe report does not choose a model, horizon or budget from the outer ranking. A condition with improved pooled metrics can still violate constraints on an individual recording, miss severe-interest events or depend on one event-bearing record. Always-alert is a required counterexample but fails the active cap. A silent model is not useful early warning. Training constraints are research assumptions and do not guarantee test burden or clinical safety.\n\n## Actual computational latency\n\nWarm batch-one model timings include fitted imputation/scaling, estimator scoring, the chosen score normalization and comparison with that fit's actual budget-5 cutoff. Pulse feature generation is timed separately on recorded record-1 pulse measurements, resetting states at replay wrap. There are 1,000 measured repetitions after 50 warmups; median/P95/P99 and raw timing samples are retained. These timings exclude waveform acquisition/filtering, physiological monitor delay and model loading; they are not an end-to-end device guarantee. Existing historical waveform/loading benchmarks remain unchanged and should not be relabeled as new-model measurements. Feature and model P95 values must not be added to claim an end-to-end P95.\n\n```text\n'''+latency[['Target','Horizon_s','FeatureSet','Model','ScoreSpace','Component','Repetitions','Median_ms','P95_ms','P99_ms']].to_string(index=False,float_format=lambda v:f'{v:.6g}')+'''\n```\n\n## Reproduction and artifacts\n\nRun in the pinned repository environment; no installation or data acquisition is needed:\n\n```bash\nOPENBLAS_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1 python -m ml_research.baseline --output results/ml_improvement/run01\nMPLCONFIGDIR=/tmp/oxygen-ml-mpl OPENBLAS_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1 python -m ml_research.experiment --output results/ml_improvement/run01\n```\n\nThose are the original executed paths. Both entry points reject an existing baseline/protocol to prevent overwrites. To reproduce after this run, use a new directory such as `results/ml_improvement/reproduction01`; reports are written inside the new directory; existing docs/ reports are retained rather than overwritten. All existing source/data/results/doc hashes are verified before/after; manifests identify outputs and code/protocol fingerprints. No pipeline cache is regenerated.\n\nOutputs include original baseline recomputations, exact horizon labels, unlabeled held-out scores, final per-sample scores/thresholds/decisions, candidate and selected training policies, split/hash ledgers, original-score parity, training-only feature analysis, pooled and per-record timestamp/event metrics, full event matches, before/after comparisons, paired recording intervals, recording influence and measured latency samples. The figures show PR curves, event counts/leads and actual burden/activity trade-offs. Missing matched leads are undefined, not zero.\n\n## Limitations, recommendation and relationship to control\n\nOnly 30 recordings, six onset-bearing recordings, 14/15 eligible onsets and three severe-interest episodes constrain every result. Correlated pulse rows and overlapping future labels are not independent trials. Missing numerics, unvalidated pulse detection, score-rank discretization, unknown monitor delays and one-reading threshold events remain limitations. Feature inference is causal; outcome labeling and exposure eligibility are necessarily retrospective and never predictor inputs. The experiment cannot prove that the feature set captures pre-onset physiology rather than correlated state. No patient identifiers, new recordings or synthetic clinical evidence were invented.\n\n'''+('Some pooled conditions meet the original assumptions while detecting events; they are hypothesis-generating observations, not a selected deployable policy. Freeze a candidate using middle recording-grouped assessment entirely inside each outer training fold before claiming a preferred model. ' if len(eligible) else 'None of the tested configurations demonstrates event detection within both original pooled alarm constraints. No model/operating policy is recommended as a useful detector. ')+'''The smallest justified next methodological step is training-only middle recording-grouped assessment of ONE prespecified candidate and the frozen baseline, with inner calibration/threshold selection, before outer evaluation; do not pick that candidate or revise budgets using the present outer table. With this repeatedly examined small cohort, even that is exploratory.\n\nFor a future feedforward study, these results could characterize an offline risk signal's reliability, burden and lead distribution. They establish no risk-to-actuator mapping, oxygen dose, oxygen plant model, benefit of intervention, PID/P/PI superiority, closed-loop stability or successful oxygen control. This task contains no actuation or PID experiment.\n\nTests and final integrity/check outcomes are appended only after those commands actually execute. Three existing historical-document hash failures remain untouched.\n'''
    text=text.replace('results/ml_improvement/run01',str(output.relative_to(ROOT)))
    (output/'ML_IMPROVEMENT_REPORT.md').write_text(text)
    if not report.exists():report.write_text(text)
    (output/'scientific_conclusion.json').write_text(json.dumps(dict(pooled_feasible_detecting_conditions=len(eligible),all_record_feasible_detecting_conditions=len(strict),model_selected=False,clinical_validation=False),indent=2))
